"""Pagination (LIB-COM-18 to LIB-COM-20)."""
from collections.abc import Sequence
from typing import Any

from fastapi import Query

from .errors import ValidationFailed


def page_params(page: str | None = Query(None), page_size: str | None = Query(None)) -> tuple[int, int]:
    fields = []
    values = []
    for name, raw, default, lo, hi in (("page", page, 1, 1, None), ("page_size", page_size, 20, 1, 100)):
        if raw is None:
            values.append(default)
            continue
        try:
            v = int(raw)
            if not raw.strip().lstrip("+-").isdigit():
                raise ValueError
        except ValueError:
            fields.append({"field": name, "problem": "must be an integer"})
            continue
        if v < lo or (hi is not None and v > hi):
            fields.append({"field": name, "problem": f"must be between {lo} and {hi}" if hi else f"must be at least {lo}"})
            continue
        values.append(v)
    if fields:
        raise ValidationFailed(fields)
    return values[0], values[1]


def paginate(items: Sequence[Any], page: int, page_size: int) -> dict[str, Any]:
    start = (page - 1) * page_size
    return {"items": list(items[start:start + page_size]), "page": page, "page_size": page_size, "total": len(items)}
